function create(
  bytes calldata encodedParameters,
  address ownedBy
) external returns (address) {

  require(roundImplementation != address(0), "roundImplementation is 0x");
  require(alloSettings != address(0), "alloSettings is 0x");

  address clone = ClonesUpgradeable.clone(roundImplementation);

  emit RoundCreated(clone, ownedBy, payable(roundImplementation));

  IRoundImplementation(payable(clone)).initialize(
    encodedParameters,
    alloSettings
  );

  return clone;
}

function __INIT_VAULT(
    string memory name_,
    uint16 borrowCurrencyId_
) internal onlyInitializing {
    _NAME = name_;
    _BORROW_CURRENCY_ID = borrowCurrencyId_;

    address underlyingAddress = _getNotionalUnderlyingToken(borrowCurrencyId_);
    _UNDERLYING_TOKEN = IERC20(underlyingAddress);
    _UNDERLYING_IS_ETH = underlyingAddress == address(0);
    _setupRole(DEFAULT_ADMIN_ROLE, NOTIONAL.owner());
}

function request (
    uint256 amount,
    uint256 interest,
    uint256 loanToCollateral,
    uint256 duration
) external returns (uint256 reqID) {
    reqID = requests.length;
    factory.newEvent(reqID, CoolerFactory.Events.Request);
    requests.push(
        Request(amount, interest, loanToCollateral, duration, true)
    );
    collateral.transferFrom(msg.sender, address(this), collateralFor(amount, loanToCollateral));
}

